(() => {
  const css=`
  .decision-strip{display:grid;grid-template-columns:1.2fr 1fr 1fr;gap:10px;margin:12px 0}.decision-card{border:1px solid var(--line);background:#f8fbfc;border-radius:14px;padding:13px}.decision-card.primary{background:#eef7f9;border-color:#b8d6df}.decision-card.warn{background:#fff9ee;border-color:#ead4a0}.decision-label{font-size:10px;color:var(--muted);font-weight:800;text-transform:uppercase;letter-spacing:.04em}.decision-value{font-size:24px;font-weight:800;margin:5px 0}.decision-card small{color:var(--muted);font-size:11px}.decision-card .btn{margin-top:9px;font-size:11px}.decision-details{margin:8px 0 12px;border:1px solid var(--line);border-radius:13px;overflow:hidden}.decision-details>summary{cursor:pointer;padding:11px 13px;font-size:12px;font-weight:750;background:#f9fbfc;display:flex;justify-content:space-between;gap:10px}.decision-details>.detail{padding:10px;margin:0}.business-note{font-size:11px;color:var(--muted);margin:-3px 0 8px}.sr-help{position:fixed;right:18px;bottom:18px;z-index:90;background:#102f3e!important;color:#fff!important;border-color:#102f3e!important;box-shadow:0 10px 26px #0003}.sr-bubble{position:fixed;right:18px;bottom:62px;z-index:91;width:min(320px,calc(100vw - 24px));background:#fff;border:1px solid var(--line);border-radius:14px;padding:13px;box-shadow:0 18px 45px #0003;font-size:12px;line-height:1.45}@media(max-width:900px){.decision-strip{grid-template-columns:1fr}.decision-card{min-height:0}}@media(max-width:780px){.decision-strip{display:flex;overflow-x:auto;margin:8px -12px;padding:0 12px 6px}.decision-card{min-width:78vw}.business-note{margin-top:0}.sr-help{right:14px;bottom:84px}.sr-bubble{left:12px;right:12px;bottom:132px;width:auto}}`;
  const style=document.createElement('style');style.id='srExecutiveStyles';style.textContent=css;document.head.appendChild(style);
  function kpi(label){const cards=[...document.querySelectorAll('#kpis .kpi')];const c=cards.find(x=>x.querySelector('small')?.textContent.includes(label));return c?.querySelector('strong')?.textContent||'0'}
  function polish(){if(typeof s==='undefined'||s.section!=='negocios')return;const main=document.getElementById('main');if(!main||main.querySelector('.decision-strip'))return;
    const qualified=kpi('Clientes precalificados'),blocked=kpi('NO-GO'),base=kpi('PDOT/PUGS urbano validado');
    const head=main.querySelector('.panel-head'),detail=main.querySelector(':scope > .detail');
    const strip=document.createElement('section');strip.className='decision-strip';strip.innerHTML=`<article class="decision-card primary"><div class="decision-label">Oportunidades para trabajar</div><div class="decision-value">${qualified}</div><small>Empieza por precalificar GAD y separar A/B de los que todavía deben madurar.</small><br><button class="btn primary" id="quickEvaluate">Precalificar GAD</button></article><article class="decision-card ${blocked!=='0'?'warn':''}"><div class="decision-label">Riesgo comercial / NO-GO</div><div class="decision-value">${blocked}</div><small>Bloqueos que deben resolverse antes de invertir tiempo en una oferta.</small><br><button class="btn" id="quickRisk">Revisar riesgo</button></article><article class="decision-card"><div class="decision-label">Base territorial validada</div><div class="decision-value">${base}/222</div><small>La referencia PDOT/PUGS mejora la estimación preliminar del cliente potencial.</small><br><button class="btn" id="quickTerritory">Ver pendientes</button></article>`;
    head?.insertAdjacentElement('afterend',strip);
    const note=document.createElement('div');note.className='business-note';note.textContent='Primero decide dónde vale la pena invertir tiempo comercial; después abre el detalle metodológico.';strip.insertAdjacentElement('afterend',note);
    if(detail){const d=document.createElement('details');d.className='decision-details';d.id='decisionDetails';d.innerHTML='<summary><span>Criterios GO/NO-GO, categorías de interés y bloqueos especiales</span><span>abrir</span></summary>';detail.replaceWith(d);d.appendChild(detail)}
    const goTable=()=>document.getElementById('marketSearch')?.scrollIntoView({behavior:'smooth',block:'center'});document.getElementById('quickEvaluate')?.addEventListener('click',goTable);
    document.getElementById('quickRisk')?.addEventListener('click',()=>{const c=document.getElementById('marketCategory');if(c){const o=[...c.options].find(x=>x.textContent.startsWith('X ·'));if(o){c.value=o.value;c.dispatchEvent(new Event('change',{bubbles:true}))}}goTable()});
    document.getElementById('quickTerritory')?.addEventListener('click',()=>{const c=document.getElementById('marketTerritoryStatus');if(c){c.value='PDOT/PUGS pendiente';c.dispatchEvent(new Event('change',{bubbles:true}))}goTable()});
    const show=document.getElementById('showCriteria');if(show)show.onclick=()=>{const d=document.getElementById('decisionDetails');if(d){d.open=true;d.scrollIntoView({behavior:'smooth',block:'start'})}};
  }
  function installHelp(){if(document.getElementById('srHelp'))return;const tips=['Empieza en Negocios / Mercado: aquí decides dónde vale la pena invertir tiempo.','Precalifica al GAD y revisa oportunidad, riesgo y capacidad de contratación.','Convierte la oportunidad en proyecto solo cuando el GO / NO-GO sea favorable.','En Mapa / Área carga KMZ, KML o GeoJSON para medir el polígono y mostrar resultados.','Usa Vista de rol para cambiar las acciones y datos según el responsable.'];let i=0;const h=document.createElement('button');h.id='srHelp';h.className='btn sr-help';h.textContent='? Guía';document.body.appendChild(h);const b=document.createElement('div');b.className='sr-bubble';b.style.display='none';document.body.appendChild(b);const show=()=>{b.style.display='block';b.innerHTML='<strong>Guía '+(i+1)+' de '+tips.length+'</strong><div style="margin:6px 0 10px;color:#60717c">'+tips[i]+'</div><button class="btn" id="srClose">Cerrar</button> <button class="btn primary" id="srNext">'+(i===tips.length-1?'Terminar':'Siguiente')+'</button>';b.querySelector('#srClose').onclick=()=>b.style.display='none';b.querySelector('#srNext').onclick=()=>{if(i===tips.length-1){b.style.display='none';i=0}else{i++;show()}}};h.onclick=()=>{i=0;show()}}
  const prev=renderMain;renderMain=function(){prev();polish()};polish();installHelp();window.SmartRiskExecutivePolish={refresh:polish};
})();
